<x-app-layout><x-page-header title="Audit Logs" description="Administrative activity history." /><form class="mt-6 grid gap-3 sm:grid-cols-4"><input name="actor" value="{{ request('actor') }}" placeholder="Actor ID" class="rounded-lg border-slate-300"><input name="entity" value="{{ request('entity') }}" placeholder="Entity" class="rounded-lg border-slate-300"><input name="action" value="{{ request('action') }}" placeholder="Action" class="rounded-lg border-slate-300"><input type="date" name="date" value="{{ request('date') }}" class="rounded-lg border-slate-300"></form><div class="mt-4"><x-data-table :headings="['Date','Actor','Action','Entity','Metadata']">@forelse($logs as $log)<tr><td class="px-5 py-3">{{ $log->created_at }}</td><td class="px-5 py-3">{{ $log->actor?->name ?? 'System' }}</td><td class="px-5 py-3">{{ $log->action }}</td><td class="px-5 py-3">{{ $log->entity_type }} #{{ $log->entity_id }}</td><td class="px-5 py-3 text-xs">{{ json_encode($log->metadata) }}</td></tr>@empty<tr><td colspan="5" class="px-5 py-8"><x-empty-state title="No audit logs" /></td></tr>@endforelse</x-data-table></div><div class="mt-4">{{ $logs->links() }}</div></x-app-layout>
